import React from 'react';

export function Switch({ label, checked = false }: { label: string; checked?: boolean }) {
  const [on, setOn] = React.useState(checked);
  return (
    <button role="switch" aria-checked={on} aria-label={label} onClick={() => setOn(!on)}
      style={{ display: 'inline-flex', alignItems: 'center', gap: '10px', border: '1px solid {{token:colors.base.border}}', background: '{{token:colors.base.surface}}', borderRadius: '999px', padding: '4px', cursor: 'pointer' }}>
      <span style={{ width: '20px', height: '20px', borderRadius: '50%', background: on ? '{{token:colors.accent.primary}}' : '{{token:colors.text.muted}}', transition: '{{token:animation.transition.default}}' }} />
      <span style={{ fontSize: '{{token:typography.scale.sm}}', color: '{{token:colors.text.primary}}' }}>{label}</span>
    </button>
  );
}

